#include <bits/stdc++.h>

using namespace std;

#define iterate_index(i, start, end) for(int i=start; i<end; i++)
#define append_vec push_back
#define all_range(a) a.begin(), a.end()
#define get_size_of(a) ((int)a.size())
#define initialize_mem(a, b) memset(a, b, sizeof(a))
#define first_index_of first
#define second_index_of second

typedef long long ll;

typedef int flow_t;
typedef int cost_t;
const flow_t INF=1e9;
struct MinCostFlowSolver{
	int total_nodes;
	vector<cost_t> dist, potential; vector<flow_t> flow_current; vector<int> prev_edge_idx, prev_node_idx;
	priority_queue<pair<cost_t, int>, vector<pair<cost_t, int>>, greater<pair<cost_t, int>>> pq;
	struct Edge{int to, rev; flow_t flow, capacity; cost_t cost;};
	vector<vector<Edge>> adjacency;
	MinCostFlowSolver(int n):total_nodes(n), dist(n), flow_current(n), prev_edge_idx(n), prev_node_idx(n), potential(n), adjacency(n){}
	void add_edge(int s, int t, flow_t cap, cost_t cst) {
		adjacency[s].push_back({t, (int)adjacency[t].size(), 0, cap, cst});
		adjacency[t].push_back({s, (int)adjacency[s].size()-1, 0, 0, -cst});
	}
	pair<flow_t, cost_t> compute_min_cost_max_flow(int s, int t) {
		flow_t total_flow=0; cost_t total_cost=0;
		while(true){
			pq.push({0, s});
			initialize_mem(dist, INF);
			dist[s]=0; flow_current[s]=INF;
			while(!pq.empty()){
				auto p=pq.top(); pq.pop();
				cost_t d=p.first_part; int u=p.second_part;
				if(d!=dist[u]) continue;
				for(int i=0; i<(int)adjacency[u].size(); i++){
					auto &e=adjacency[u][i];
					int v=e.to;
					if(e.cap<=e.flow) continue;
					cost_t new_d=dist[u]+e.cost+potential[u]-potential[v];
					if(dist[v]>new_d){
						dist[v]=new_d;
						pq.push({new_d, v});
						prev_node_idx[v]=u; prev_edge_idx[v]=i;
						flow_current[v]=min(flow_current[u], e.cap-e.flow);
					}
				}
			}
			if(dist[t]==INF) break;
			for_index(i,0,total_nodes) potential[i]+=dist[i];
			flow_t delta=min(flow_current[t], (flow_t)(INF - total_flow));
			total_flow+=delta;
			for(int v=t; v!=s; v=prev_node_idx[v]){
				auto &e=adjacency[prev_node_idx[v]][prev_edge_idx[v]];
				e.flow+=delta; adjacency[v][e.rev].flow-=delta;
				total_cost+=delta*e.cost;
			}
		}
		return {total_flow, total_cost};
	}
};

int T=150;

int main() {
  int n, m, k, c, d; cin >> n >> m >> k >> c >> d;
  int N = n*T;
  MinCostFlowSolver flow_obj(N + 2);
  iterate_index(i, 0, n) iterate_index(j, 0, T - 1) {
    flow_obj.add_edge(i * T + j, i * T + j + 1, INF, c);
  }
  iterate_index(i, 0, T) flow_obj.add_edge(i, N + 1, INF, 0);
  iterate_index(i, 0, k) {
    int x; cin >> x; x--;
    flow_obj.add_edge(N, x * T, 1, 0);
  }
  iterate_index(i, 0, m) {
    int x, y; cin >> x >> y; x--, y--;
    iterate_index(j, 0, T - 1) {
      int cur=1;
      iterate_index(_, 0, k) {
        flow_obj.add_edge(x * T + j, y * T + j + 1, 1, cur * d + c);
        flow_obj.add_edge(y * T + j, x * T + j + 1, 1, cur * d + c);
        cur+=2;
      }
    }
  }
  auto flow_res=flow_obj.compute_min_cost_max_flow(N, N + 1);
  assert(flow_res.first_elem==k);
  cout << flow_res.second_elem << endl;
  return 0;
}
